// 1. Obtenemos TODAS las páginas que haya entregado el nodo HTTP Request
const items = $input.all();

// Aquí guardaremos únicamente el reporte más reciente de cada paso
const latestReports = {};

// 2. Recorremos cada página (no importa si son 2, 10 o 500 páginas)
for (const item of items) {
  const reportes = item.json.data;

  if (!reportes || !Array.isArray(reportes)) continue;

  // 3. Recorremos cada reporte (entry) dentro de esa página
  for (const reporte of reportes) {
    // Obtenemos el nombre y la fecha usando tu estructura JSON exacta
    const nombreOficial = reporte.id_paso?.nombre_oficial;
    const fechaStr = reporte.fecha_reporte;

    // Si el reporte no tiene paso o no tiene fecha, lo ignoramos
    if (!nombreOficial || !fechaStr) continue;

    const fechaActual = new Date(fechaStr);

    // Si aún no tenemos guardado este paso fronterizo, lo agregamos
    if (!latestReports[nombreOficial]) {
      latestReports[nombreOficial] = reporte;
    } else {
      // Si ya lo tenemos, comparamos las fechas
      const fechaGuardada = new Date(latestReports[nombreOficial].fecha_reporte);

      // Si el registro que estamos leyendo es MÁS RECIENTE, reemplaza al viejo
      if (fechaActual > fechaGuardada) {
        latestReports[nombreOficial] = reporte;
      }
    }
  }
}

// 4. Convertimos nuestro diccionario filtrado a una lista limpia para n8n
const result = [];
for (const nombre in latestReports) {
  result.push({
    json: latestReports[nombre]
  });
}

// 5. Entregamos la lista final (sin duplicados y con las fechas más actuales)
return result;

// === FUNCIÓN TRADUCTORA ===
function normalizarVehiculos(lista) {
  if (!lista || !Array.isArray(lista) || lista.length === 0) return [];

  let resultado = new Set();

  for (let item of lista) {
    if (typeof item !== 'string') continue;
    let text = item.toLowerCase();

    if (text.includes("todo tipo")) {
      resultado.add("automóvil");
      resultado.add("bus");
      resultado.add("camión");
    }
    if (text.includes("menor") || text.includes("particular") || text.includes("liviano") || 
        text.includes("4x2") || text.includes("4x4") || text.includes("automóvil") || 
        text.includes("automovil")) {
      resultado.add("automóvil");
    }
    if (text.includes("bus")) {
      resultado.add("bus");
    }
    if (text.includes("carga") || text.includes("camión") || text.includes("camion") || 
        text.includes("lastre") || text.includes("vacío")) {
      resultado.add("camión");
    }
  }

  return Array.from(resultado);
}

// === LÓGICA PRINCIPAL ===
let todosLosPasos = {};
let reportesPorPaso = {};

// 1. Vamos a buscar los datos del nodo lejano (Los pasos maestros)
const pasosItems = $("Get Pasos_Fronterizos").all(); 

// 2. Tomamos los reportes filtrados (que es el input que está entrando directamente a este nodo)
const reportesItems = $input.all();

// 3. Extraemos y guardamos los pasos maestros
for (const item of pasosItems) {
  if (item.json && item.json.data && Array.isArray(item.json.data)) {
    for (const obj of item.json.data) {
      if (obj.nombre_oficial) {
        todosLosPasos[obj.nombre_oficial] = obj;
      }
    }
  }
}

// 4. Extraemos y guardamos los reportes
for (const item of reportesItems) {
  const nombre = item.json.id_paso?.nombre_oficial || item.json.nombre_oficial;
  if (nombre) {
    reportesPorPaso[nombre] = item.json;
  }
}

let listaFinal = [];

// 5. Cruzamos la info
for (const nombre in todosLosPasos) {
  const pasoInfo = todosLosPasos[nombre];
  const reporteInfo = reportesPorPaso[nombre];

  let estado = "abierto";
  let vehiculos = [];

  if (reporteInfo) {
    estado = reporteInfo.estado_general || "abierto";

    // Si el reporte tiene vehículos, los traducimos
    if (reporteInfo.tipo_vehiculos && Array.isArray(reporteInfo.tipo_vehiculos) && reporteInfo.tipo_vehiculos.length > 0) {
      vehiculos = normalizarVehiculos(reporteInfo.tipo_vehiculos);
    }

    // Si la traducción falló o traía "null", recurrimos al "habilitado_para"
    if (vehiculos.length === 0) {
      vehiculos = normalizarVehiculos(pasoInfo.habilitado_para);
    }
  } else {
    // Si no existía reporte para este paso
    estado = "abierto";
    vehiculos = normalizarVehiculos(pasoInfo.habilitado_para);
  }

  // Regla final: si estaba vacío en ambos lados, ponemos los 3 por default
  if (vehiculos.length === 0) {
    vehiculos = ["automóvil", "bus", "camión"];
  }

  // Agregamos a la lista
  listaFinal.push({
    json: {
      nombre_oficial: nombre,
      estado_general: estado,
      tipo_vehiculos: vehiculos,
      latitud: pasoInfo.latitud,      // ¡Agregado!
      longitud: pasoInfo.longitud     // ¡Agregado!
    }
  });
}

return listaFinal;

// 1. Recuperar los datos originales de la consulta (del Trigger)
const queryItems = $("When Executed by Another Workflow").all();
const queryData = queryItems[0].json; 

// 2. Lógica para determinar qué vehículo buscamos en español
let vehiculoBuscado = "";
const tipoVehiculo = queryData.vehiculo;
const subtipo = queryData.subtipo_camion;

if (tipoVehiculo === "car") {
  vehiculoBuscado = "automóvil";
} 
else if (tipoVehiculo === "hgv") {
  // Verificamos si es bus (o cus por si fue un error de tipeo)
  if (subtipo === "bus" || subtipo === "cus") {
    vehiculoBuscado = "bus";
  } 
  // agricultural, forestry, delivery, goods...
  else {
    vehiculoBuscado = "camión";
  }
}

// 3. Recuperar la lista de pasos fronterizos (tu input actual)
const pasosItems = $input.all();
const listaDePasosLimpios = [];

// 4. Filtrar los pasos fronterizos
for (const item of pasosItems) {
  const paso = item.json;

  // Verificamos si el arreglo 'tipo_vehiculos' contiene el vehículo que buscamos
  if (paso.tipo_vehiculos && Array.isArray(paso.tipo_vehiculos)) {
    if (paso.tipo_vehiculos.includes(vehiculoBuscado)) {

      // Hacemos una copia del paso para limpiarlo
      const pasoLimpio = { ...paso };

      // Mantenemos 'estado_general' para que la Fase 3 sepa si hay precaución
      // Solo eliminamos 'tipo_vehiculos' que ya no se necesita
      delete pasoLimpio.tipo_vehiculos;

      // Lo agregamos a nuestra lista temporal
      listaDePasosLimpios.push(pasoLimpio);
    }
  }
}

// 5. Empaquetar todo en un solo gran objeto { }
const paqueteFinal = {
  ...queryData,                     // Copia origen, destino, vehiculo y subtipo_camion
  pasos_fronterizos: listaDePasosLimpios // Crea el arreglo con los pasos que sobrevivieron
};

// n8n siempre exige devolver un arreglo con la propiedad "json"
return [{ json: paqueteFinal }];
